export{ModalDatoAdicionalArticuloCtrl};function ModalDatoAdicionalArticuloCtrl($scope,$uibModalInstance,params){let{entity:entity,datosAdicionales:datosAdicionales}=params,dataEtiqueta=entity.etiquetas[0];$scope.articulo=entity,$scope.etiquetas=JSON.parse(dataEtiqueta.etiquetas[0]),$scope.data=[];let dataInfo=datosAdicionales.info.find(item=>item.idArticulo===$scope.articulo.idArticulo);dataInfo&&($scope.data=dataInfo.adicionales),$scope.addRow=function(){$scope.data.length!==$scope.articulo.cantidad?$scope.data.push({}):Swal.fire({title:"Datos Adicionales",icon:"warning",html:`El número de datos adicionales proporcionados no debe exceder la cantidad de artículo: <b>${$scope.articulo.descripcion}</b>!`})},$scope.removeRow=function(row){try{Swal.fire({title:"Eliminar Dato Adicional",icon:"warning",html:"Esta seguro de eliminar este dato adicional?",showConfirmButton:!0,showCancelButton:!0,cancelButtonText:"No, cancelar",confirmButtonText:"Si, eliminar"}).then(result=>{if(result.isConfirmed){let index=$scope.data.indexOf(row);$scope.data.splice(index,1),$scope.$apply()}})}catch(error){console.log(error)}},$scope.save=function(){try{if(0===$scope.data.length)return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"Ingrese los datos adicionales del artículo!"});for(let data of $scope.etiquetas)for(let item of $scope.data)if([null,void 0,""].includes(item[data.codigo]))return void Swal.fire({title:"Datos Adicionales",icon:"warning",html:"Ingrese todos campos!"});$uibModalInstance.close({isAdd:!0,data:$scope.data.map(item=>{let{$$hashKey:$$hashKey,...rest}=item;return rest})})}catch(error){console.log(error)}},$scope.closeModal=function(){$uibModalInstance.close()}}ModalDatoAdicionalArticuloCtrl.$inject=["$scope","$uibModalInstance","params"];